<?php require_once __DIR__ . '/../includes/functions.php'; require_once __DIR__ . '/../includes/database.php'; admin_required(); try{$pdo=db();$total=(int)$pdo->query('SELECT COUNT(*) FROM contact_messages')->fetchColumn();$unread=(int)$pdo->query("SELECT COUNT(*) FROM contact_messages WHERE status='unread'")->fetchColumn();$recent=$pdo->query('SELECT id,name,email,project_type,status,created_at FROM contact_messages ORDER BY id DESC LIMIT 6')->fetchAll();}catch(Throwable $e){$total=$unread=0;$recent=[];} ?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin dashboard | VeytronaTech</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><header class="site-header scrolled"><div class="nav shell"><a class="brand" href="../index.php"><span class="brand-mark">V</span><span>VEYTRONA<span>TECH</span></span></a><nav class="nav-links" style="display:flex"><a href="dashboard.php">Dashboard</a><a href="messages.php">Messages</a><a href="logout.php">Logout</a></nav></div></header><main class="shell"><section class="page-hero"><p class="eyebrow">Admin</p><h1>Dashboard</h1><p>Review project enquiries and manage their status.</p></section><section class="principles"><article class="principle"><span class="icon">#</span><h3><?= $total ?></h3><p>Total messages</p></article><article class="principle"><span class="icon">●</span><h3><?= $unread ?></h3><p>Unread messages</p></article></section><section class="section"><div class="section-head"><h2 class="section-title">Recent messages</h2><a class="text-link" href="messages.php">View all <span>→</span></a></div><div class="form-card" style="overflow:auto"><table class="admin-table"><thead><tr><th>Name</th><th>Project</th><th>Status</th><th>Received</th></tr></thead><tbody><?php foreach($recent as $m): ?><tr><td><a href="messages.php?view=<?=$m['id']?>"><?=e($m['name'])?></a><br><span class="muted"><?=e($m['email'])?></span></td><td><?=e($m['project_type'])?></td><td><?=e(ucfirst($m['status']))?></td><td><?=e($m['created_at'])?></td></tr><?php endforeach ?><?php if(!$recent): ?><tr><td colspan="4">No messages yet.</td></tr><?php endif ?></tbody></table></div></section></main></body></html>
